// Забираем ВЕСЬ каталог постранично (по 100), а не первую сотню.
// Токен приходит от узла «Выпустить токен».
const token = $input.first().json.access_token;
const url = 'https://kmfmxn-r4.myshopify.com/admin/api/2026-07/graphql.json';
const query = `query($cursor: String) {
  products(first: 100, after: $cursor) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id title status handle featuredImage { url }
      style: metafield(namespace: "artmellio", key: "style") { value }
      material: metafield(namespace: "artmellio", key: "material") { value }
      room: metafield(namespace: "artmellio", key: "room") { value }
      palette: metafield(namespace: "artmellio", key: "palette") { value }
      pairs: metafield(namespace: "artmellio", key: "pairs_with") { value }
    }
  }
}`;

const all = [];
let cursor = null;
let pages = 0;
do {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
    body: { query, variables: { cursor } },
    json: true,
  });
  if (r.errors) throw new Error('Shopify: ' + JSON.stringify(r.errors));
  const page = r.data.products;
  all.push(...page.nodes);
  cursor = page.pageInfo.hasNextPage ? page.pageInfo.endCursor : null;
  pages += 1;
} while (cursor && pages < 100);

return [{ json: { data: { products: { nodes: all } }, страниц: pages } }];

// Считаем, чего не хватает карточкам. Только чтение. На выходе:
// сводка (цифры), строки для таблицы (по одной на товар с пробелами),
// текст для Telegram и признак «запущено по расписанию».
const FIELDS = ['style', 'material', 'room', 'palette'];
const NAMES = { style: 'стиль', material: 'материал', room: 'комната', palette: 'палитра', image: 'картинка', pairs: 'пара' };
const nodes = $input.first().json.data.products.nodes;

const empty = (v) => {
  if (!v || !v.value) return true;
  const t = String(v.value).trim();
  return t === '' || t === '[]';
};

const gaps = {};
FIELDS.forEach((f) => (gaps[f] = []));
const noImage = [];
const noPairs = [];
const rows = [];

for (const p of nodes) {
  const missing = [];
  FIELDS.forEach((f) => { if (empty(p[f])) { gaps[f].push(p.title); missing.push(f); } });
  if (!p.featuredImage) { noImage.push(p.title); missing.push('image'); }
  if (empty(p.pairs)) { noPairs.push(p.title); missing.push('pairs'); }
  if (!missing.length) continue;
  const row = {
    'Товар': p.title,
    'Статус': p.status === 'ACTIVE' ? 'активен' : p.status === 'DRAFT' ? 'черновик' : 'архив',
    'Пропусков': missing.length,
    'Чего нет': missing.map((m) => NAMES[m]).join(', '),
  };
  for (const k of [...FIELDS, 'image', 'pairs']) row[NAMES[k]] = missing.includes(k) ? 'нет' : '';
  row['Открыть в админке'] = 'https://admin.shopify.com/store/kmfmxn-r4/products/' + p.id.split('/').pop();
  row['Витрина'] = 'https://www.artmellio.com/products/' + p.handle;
  rows.push(row);
}
// Сначала самые «дырявые»
rows.sort((a, b) => b['Пропусков'] - a['Пропусков'] || a['Товар'].localeCompare(b['Товар']));

const сводка = {
  всего: nodes.length,
  с_пробелами: rows.length,
  без_картинки: noImage.length,
  без_pairs_with: noPairs.length,
};
FIELDS.forEach((f) => (сводка['без_' + f] = gaps[f].length));

let from_schedule = false;
try { from_schedule = $('Каждое утро в 9').isExecuted === true; } catch (e) { from_schedule = false; }

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Date().toLocaleDateString('ru-RU', { timeZone: 'Europe/Warsaw' });
const telegram_text = [
  `📋 <b>Сводка пробелов каталога</b> · ${today}`,
  `Товаров: ${nodes.length}, с пробелами: ${rows.length}`,
  `Без стиля ${gaps.style.length} · материала ${gaps.material.length} · комнаты ${gaps.room.length} · палитры ${gaps.palette.length}`,
  `Без картинки ${noImage.length} · без пары ${noPairs.length}`,
  `Таблица: панель → «Отчёты» → catalog-gaps`,
].map(esc).join('\n').replace(/&lt;b&gt;/g, '<b>').replace(/&lt;\/b&gt;/g, '</b>');

return [{ json: { сводка, примеры: {
  без_материала: gaps.material.slice(0, 10),
  без_стиля: gaps.style.slice(0, 10),
  без_картинки: noImage.slice(0, 10),
}, rows, telegram_text, from_schedule,
  telegram_on: from_schedule && Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID) } }];

// Ответ для панели: цифры, примеры и ссылки на файл отчёта.
const s = $('Собрать сводку').first().json;
let rep = {};
try { rep = $('Отчёт в панель').first().json || {}; } catch (e) { rep = {}; }
const out = { сводка: s.сводка };
if (rep.xlsx_url) {
  out.отчёт = { строк: rep.rows, excel: rep.xlsx_url, csv: rep.csv_url, папка: rep.folder };
} else {
  out.отчёт = { файл: 'не записан — панель не ответила (запущена ли panel\start-panel.ps1?)' };
}
out.примеры = s.примеры;
out.telegram = s.from_schedule ? (s.telegram_on ? 'отправлено' : 'ключей нет') : 'только по расписанию';
return [{ json: out }];
